package com.meterflow.budgets;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class BudgetService{private final UsageBudgetRepository repo;private final com.meterflow.metering.UsageService usage;private final com.meterflow.notifications.WebhookDeliveryService webhooks;public BudgetService(UsageBudgetRepository r,com.meterflow.metering.UsageService u,com.meterflow.notifications.WebhookDeliveryService w){repo=r;usage=u;webhooks=w;}
@Transactional public UsageBudget set(String c,String p,BigDecimal a,String currency){if(a==null||a.signum()<=0)throw new IllegalArgumentException("Budget must be positive");YearMonth.parse(p);var b=repo.findByCustomerIdAndPeriod(c,p).orElseGet(()->new UsageBudget(c,p,a,currency));if(!b.getCurrency().equals(currency))throw new IllegalArgumentException("Budget currency cannot change within a period");b.update(a);return repo.save(b);}
@Transactional public Map<String,Object> evaluateIfConfigured(String c,String p){if(repo.findByCustomerIdAndPeriod(c,p).isEmpty())return Map.of("status","NO_BUDGET");return evaluate(c,p);}
@Transactional public Map<String,Object> evaluate(String c,String p){var b=repo.findByCustomerIdAndPeriod(c,p).orElseThrow(()->new IllegalArgumentException("Budget not configured"));var estimate=usage.estimate(c);BigDecimal amount=new BigDecimal(estimate.get("estimatedAmount").toString());if(!b.getCurrency().equals(estimate.get("currency")))throw new IllegalStateException("Budget and plan currency mismatch");int pct=amount.multiply(BigDecimal.valueOf(100)).divide(b.getAmount(),0,RoundingMode.DOWN).intValue();List<Integer> fired=new ArrayList<>();for(int n:new int[]{50,80,100})if(pct>=n&&!b.wasNotified(n)){b.mark(n);fired.add(n);webhooks.publish(c,"usage.threshold_reached",Map.of("customerId",c,"period",p,"threshold",n,"estimatedAmount",amount,"budget",b.getAmount()));}repo.save(b);return Map.of("customerId",c,"period",p,"budget",b.getAmount(),"estimatedAmount",amount,"percentUsed",pct,"newAlerts",fired);}}
